package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.repository.jobs.*;
import java.time.*;
import org.junit.jupiter.api.*;
/** Explicit-cutoff facts use real native events and real postcommit first observations. */
class EntityHeatSupplementCutoffProofTest {
 boolean mysql(){return false;}
 EntityHeatCutoffProofTest h;
 @BeforeEach void setup(){h=new EntityHeatCutoffProofTest(){@Override GenerationJdbcStoreTest fixture(){return EntityHeatSupplementCutoffProofTest.this.mysql()?new GenerationJdbcStoreMySqlTest():new GenerationJdbcStoreTest();}};h.setup();h.h.service.capture(h.h.h.id);}
 @Test void ActualLaterObservedRevisionBelongsOnlyToTheNewExplicitCutoff(){var old=h.service.capture(h.cutoff);String later=h.append("fictional-explicit-later",4,19,h.cutoff.plusSeconds(1));Instant cutoff=h.cutoff.plusSeconds(2).plusNanos(1000);h.h.observer(Clock.fixed(cutoff,ZoneOffset.UTC),h.h.h.h.f.writes).capture(later);var current=h.service.captureSupplement(cutoff);assertEquals(cutoff,current.cutoff());assertEquals(19,current.counts().get("fictional-new").snapshot().occurrenceCount());assertEquals(later,current.counts().get("fictional-new").eventId());assertEquals(1,old.counts().get("fictional-new").snapshot().occurrenceCount());assertEquals(old.counts(),h.service.capture(h.cutoff).counts());assertSame(current,h.h.h.rr(()->h.service.verifyObserved(current)));assertEquals(0,h.h.h.h.f.count("record_kind='ai_attempt' OR record_kind='logical_task'"));}
 @Test void UnobservedAndMicrosecondLateFirstCannotFallBackToAnOlderCount(){Instant cutoff=h.cutoff.plusSeconds(10).plusNanos(1000);String later=h.append("fictional-explicit-unobserved",4,7,cutoff.minusNanos(1000));var missing=h.service.captureSupplement(cutoff);assertFalse(missing.counts().containsKey("fictional-new"));assertTrue(missing.gaps().contains(new EntityHeatCutoffProofService.Gap("fictional-new","count_unobserved_at_cutoff")));h.h.observer(Clock.fixed(cutoff.plusNanos(1000),ZoneOffset.UTC),h.h.h.h.f.writes).capture(later);assertEquals(missing.gaps(),h.service.captureSupplement(cutoff).gaps());assertEquals(7,h.service.captureSupplement(cutoff.plusNanos(1000)).counts().get("fictional-new").snapshot().occurrenceCount());}
 @Test void EntireOriginalUniverseIsRetainedAndCapacityIssuerAndDamageStillReject(){for(int i=0;i<130;i++)h.h.h.h.entity(String.format("fictional-explicit-head-%03d",i),1);Instant cutoff=h.cutoff.plusSeconds(9);var value=h.service.captureSupplement(cutoff);assertEquals(131,value.gaps().size());assertThrows(RuntimeException.class,()->h.create(1024).captureSupplement(cutoff));assertThrows(RuntimeException.class,()->h.h.h.rr(()->h.create(EntityHeatCutoffProofService.MAX_ORIGINAL_BYTES).verifyObserved(value)));h.h.h.h.f.jdbc.update("UPDATE jobs SET reason='Fictional changed event' WHERE id=?",h.h.h.id);assertThrows(RuntimeException.class,()->h.h.h.rr(()->h.service.verifyObserved(value)));}
 @Test void OriginalInitialFiveClockAndExplicitMicrosecondTransactionBoundariesRemainDistinct(){Instant cutoff=h.cutoff.plusSeconds(3).plusNanos(1000);assertThrows(RuntimeException.class,()->h.service.capture(cutoff));assertThrows(RuntimeException.class,()->h.service.captureSupplement(null));assertThrows(RuntimeException.class,()->h.service.captureSupplement(cutoff.plusNanos(1)));assertThrows(RuntimeException.class,()->h.h.h.rr(()->h.service.captureSupplement(cutoff)));assertThrows(RuntimeException.class,()->h.h.h.h.write(()->h.service.captureSupplement(cutoff)));assertNotNull(h.service.captureSupplement(cutoff));}
}
